<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Snake Game</title>
    <style>
        body {
            background-color: #121212; /* Dark theme */
            color: white;
            font-family: sans-serif;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            height: 100vh;
            margin: 0;
        }

        #score {
            font-size: 24px;
            margin-bottom: 15px;
            font-weight: bold;
        }

        canvas#snake {
            background-color: #1e1e1e;
            box-shadow: 0 0 10px rgba(0,0,0,0.7);
            border-radius: 4px;
            width: 400px; /* At least 400x400 CSS pixels */
            height: 400px;
            display: block; /* Prevent scrollbar issues */
        }

        .controls {
            margin-top: 20px;
            display: flex;
            gap: 10px;
        }

        button {
            padding: 8px 16px;
            font-size: 16px;
            background-color: #333;
            color: white;
            border: none;
            border-radius: 4px;
            cursor: pointer;
            transition: background-color 0.2s ease;
        }

        button:hover {
            background-color: #555;
        }
    </style>
</head>
<body>

<div id="score">Score: 0</div>
<canvas id="snake" width="400" height="400"></canvas>

<div class="controls">
    <button id="start">Start</button>
    <button id="pause">Pause</button>
    <button id="reset">Reset</button>
</div>

<script>
(function() {
    // Configuration
    const CELL_SIZE = 20;
    const GRID_W = 400 / CELL_SIZE; // 20 cells (>=10)
    const GRID_H = 400 / CELL_SIZE; // 20 cells

    let snakeArr = [];   // Array of objects {x, y}. Index 0 is HEAD.
    let foodPos = null;  // Object {x, y}

    let currentDir = 'right'; // Direction currently moving in the grid (applied)
    let nextDirBuffer = 'right'; // Input to apply on next tick

    let scoreVal = 0;
    let isAlive = true;
    let gameLoopId = null;

    const canvas = document.getElementById('snake');
    const ctx = canvas.getContext('2d');
    const scoreEl = document.getElementById('score');

    function initGame() {
        // Snake starts length >= 3. Start centered, moving right.
        snakeArr = [
            { x: 10, y: 10 }, // HEAD (index 0)
            { x: 9, y: 10 }, 
            { x: 8, y: 10 }   // TAIL (last index)
        ];

        scoreVal = 0;
        isAlive = true;
        currentDir = 'right';
        nextDirBuffer = 'right';

        spawnFood();
        draw(); 
    }

    function spawnFood() {
        let valid = false;
        while (!valid) {
            const fx = Math.floor(Math.random() * GRID_W);
            const fy = Math.floor(Math.random() * GRID_H);

            // Check if food overlaps with any part of the snake
            let occupied = false;
            for (const part of snakeArr) {
                if (part.x === fx && part.y === fy) {
                    occupied = true;
                    break;
                }
            }

            if (!occupied) {
                foodPos = { x: fx, y: fy };
                valid = true;
            }
        }
    }

    // Expose Game API on window
    window.game = {
        w: GRID_W,
        h: GRID_H,

        reset: initGame,

        tick: function() {
            if (!isAlive) return;

            currentDir = nextDirBuffer; // Apply buffered direction to movement vector

            const head = snakeArr[0];
            let newHead = { x: head.x, y: head.y };

            switch (currentDir) {
                case 'up':    newHead.y--; break;
                case 'down':  newHead.y++; break;
                case 'left':  newHead.x--; break;
                case 'right': newHead.x++; break;
            }

            // Check Wall Collision (Ends Game)
            if (newHead.x < 0 || newHead.x >= GRID_W || 
                newHead.y < 0 || newHead.y >= GRID_H) {
                isAlive = false;
                return;
            }

            // Check Self Collision (Ends Game)
            for (const part of snakeArr) {
                if (part.x === newHead.x && part.y === newHead.y) {
                    isAlive = false;
                    return;
                }
            }

            const ateFood = (newHead.x === foodPos.x && newHead.y === foodPos.y);

            snakeArr.unshift(newHead); // Add head to front

            if (ateFood) {
                scoreVal++;
                spawnFood();
            } else {
                snakeArr.pop(); // Remove tail (maintain length)
            }

            isAlive = true; // Successfully moved, stay alive

            draw(); // Render frame after update
        },

        setDir: function(dir) {
            const opposites = { 'up': 'down', 'down': 'up', 'left': 'right', 'right': 'left' };

            // Ignore 180° reversals relative to current heading (currentDir)
            if (opposites[dir] === currentDir) {
                return; 
            }

            nextDirBuffer = dir;
        },

        setFood: function(x, y) {
            foodPos = { x: parseInt(x), y: parseInt(y) };
            draw(); // Redraw to reflect change immediately (for grading)
        },

        snake: function() {
            // Return array of [x,y], HEAD FIRST
            return snakeArr.map(p => [p.x, p.y]);
        },

        food: function() {
            if (!foodPos) return null;
            return [foodPos.x, foodPos.y];
        },

        alive: function() {
            return isAlive;
        },

        score: function() {
            return scoreVal;
        }
    };

    // UI Logic
    document.getElementById('start').addEventListener('click', () => {
        if (!gameLoopId) {
            gameLoopId = setInterval(() => {
                window.game.tick();
            }, 100); 
        }
    });

    document.getElementById('pause').addEventListener('click', () => {
        clearInterval(gameLoopId);
        gameLoopId = null;
    });

    document.getElementById('reset').addEventListener('click', () => {
        clearInterval(gameLoopId);
        gameLoopId = null;
        initGame();
    });

    // Keyboard Control for Steer Snake (Arrow Keys)
    window.addEventListener('keydown', e => {
        if (!window.game.alive()) return;

        switch(e.key) {
            case 'ArrowUp':     window.game.setDir('up'); break;
            case 'ArrowDown':   window.game.setDir('down'); break;
            case 'ArrowLeft':   window.game.setDir('left'); break;
            case 'ArrowRight':  window.game.setDir('right'); break;
        }
    });

    // Initial Draw (Empty)
    draw(); 

})();
</script>
</body>
</html>
